```python
import os
import random
from PIL import Image
from PIL.ExifTags import TAGS

class ImageAnalysisTag:
    def __init__(self, file_path):
        self.file_path = file_path
        self.dimensions = self.generate_dimensions(file_path)
        self.hash_value = self.generate_hash()
        self.exif_data = self.extract_exif_metadata(file_path)

    @staticmethod
    def generate_hash(start=0, end=1000):
        return random.randint(start, end)

    @staticmethod
    def extract_exif_metadata(image_file):
        img = Image.open(image_file)
        exif_data = {}
        info = img._getexif()
        if info is not None:
            for tag, value in info.items():
                decoded = TAGS.get(tag, tag)
                exif_data[decoded] = value
        return exif_data

    @staticmethod
    def generate_dimensions(image_file):
        with Image.open(image_file) as img:
            return img.size

def create_image_tags(directory, num_tags=10):
    image_files = [f for f in os.listdir(directory) if f.endswith('.jpg') or f.endswith('.png')]

    tags = []
    for i in range(num_tags):
        file_path = os.path.join(directory, image_files[i])
        tag = ImageAnalysisTag(file_path)
        tags.append(tag)

    return tags
```

