```python
from sqlalchemy import create_engine, MetaData, Table, select, Column
import random

# Set up database connection
DATABASE_URI = 'postgresql://user:password@localhost/dbname'
engine = create_engine(DATABASE_URI)
metadata = MetaData()

def generate_random_records(table_name, num_records, attr_probability):
    table = Table(table_name, metadata, autoload_with=engine)

    records = []
    for _ in range(num_records):
        record = {}
        for column in table.columns:
            if random.random() < attr_probability[column.name]:
                record[column.name] = generate_value_for_type(column.type)
        records.append(record)
    return records

def generate_value_for_type(column_type):
    if isinstance(column_type, String):
        return ''.join(random.choice('abcdefghijklmnopqrstuvwxyz') for _ in range(10))
    elif isinstance(column_type, Integer):
        return random.randint(-2**31, 2**31 - 1)
    # Add other types as needed...

def sort_records(records, columns, order='asc'):
    records.sort(key=lambda r: tuple(r[c] for c in columns), reverse=order == 'desc')
    return records
```
