import hashlib
import os
import sys

def process_file_in_chunks(file_path, chunk_size=65536):
    hasher = hashlib.sha256()
    if not isinstance(file_path, str) or not os.path.isfile(file_path):
        raise ValueError(""Invalid input type or file not found."")
    with open(file_path, 'rb') as file:
        for chunk in iter(lambda: file.read(chunk_size), b''):
            hasher.update(chunk)
    return hasher.hexdigest()

def test_sha256_calculation(file_path):
    try:
        calculated_hash = process_file_in_chunks(file_path)
        print(f""The SHA-256 hash for {file_path} is: {calculated_hash}"")
        return calculated_hash
    except FileNotFoundError:
        print(""Error: File not found."")

def check_file_accessibility(file_path):
    if not os.access(file_path, os.R_OK):
        raise PermissionError(""Insufficient permissions to access or read the specified file."")

def main():
    if len(sys.argv) < 2:
        print(""Usage: python script.py <file_path>"")
        sys.exit(1)
    test_file = sys.argv[1]
    check_file_accessibility(test_file)
    calculated_hash = test_sha256_calculation(test_file)

if __name__ == ""__main__"":
    main()
