import os
import random
import string
import shutil

def generate_unique_filenames(directory_path, prefix):
    def get_free_filename(prefix, directory_path):
        counter = 1
        while True:
            filename = f""{prefix}{counter}.txt""
            filepath = os.path.join(directory_path, filename)
            if not os.path.exists(filepath):
                return filename
            counter += 1

    def create_file(filename):
        try:
            with open(filename, 'w') as file:
                file.write("""".join(random.choices(string.ascii_uppercase + string.digits, k=10)))
            return True
        except Exception as e:
            print(f""Error creating {filename}: {e}"")
            return False

    filenames = set()
    counter_limit = 5  # Just an example limit for testing purposes

    while len(filenames) < counter_limit:
        free_filename = get_free_filename(prefix, directory_path)
        if free_filename is None:
            print(""Could not find a free filename"")
            return 1

        filepath = os.path.join(directory_path, free_filename)

        if os.path.exists(filepath):
            print(f""File {filepath} already exists"")
            continue

        success = create_file(free_filename)

        if success:
            filenames.add(free_filename)

    return 0

def test_generate_unique_filenames():
    test_directory_path = ""test_directory""

    try:
        shutil.rmtree(test_directory_path)
    except FileNotFoundError:
        pass

    os.makedirs(test_directory_path)

    result_code = generate_unique_filenames(test_directory_path, ""test_"")

if __name__ == ""__main__"":
