import hashlib
import concurrent.futures
import os

def process_file_in_chunks(file_path: str) -> bytes:
    chunk_size = 1024 * 1024
    hash_object = hashlib.md5()
    with open(file_path, 'rb') as file:
        while True:
            chunk = file.read(chunk_size)
            if not chunk:
                break
            hash_object.update(chunk)
    return hash_object.digest()

def process_file_entirely(file_path: str) -> bytes:
    with open(file_path, 'rb') as file:
        content = file.read()
        return hashlib.md5(content).digest()

def calculate_md5_hashes(paths: list[str], chunk_mode: bool = False) -> dict[str, str]:
    results = {}

    if not chunk_mode:
        executor = concurrent.futures.ProcessPoolExecutor()
        futures_to_paths = {executor.submit(process_file_entirely, path): path for path in paths}
        for future in concurrent.futures.as_completed(futures_to_paths):
            path = futures_to_paths[future]
            try:
                results[path] = future.result().hex()
            except Exception as e:
                results[path] = f""Error calculating MD5: {str(e)}""

        executor.shutdown(wait=True)

    else:
        for path in paths:
            try:
                results[path] = process_file_in_chunks(path).hex()
            except Exception as e:
                results[path] = f""Error calculating MD5: {str(e)}""

    return results

# Example usage
file_paths = ['path/to/file1.txt', 'path/to/file2.txt']
md5_results_chunked_mode = calculate_md5_hashes(file_paths, True)
md5_results_entire_mode = calculate_md5_hashes(file_paths)

print(""MD5 Hashes calculated using chunks:"", md5_results_chunked_mode)
print(""MD5 Hashes calculated entirely:"", md5_results_entire_mode)
```
