import hashlib
from typing import Tuple, Union

def calculate_file_hashes(filepath: str, chunk_size: int = 8192, 
                          calculate_sha256: bool = False) -> Union[Tuple[str], Tuple[str, str]]:
    md5_hash = hashlib.md5()

    if calculate_sha256:
        sha256_hash = hashlib.sha256()

    try:
        with open(filepath, 'rb') as f:
            chunk = f.read(chunk_size)

            while chunk:
                md5_hash.update(chunk)

                if calculate_sha256:
                    sha256_hash.update(chunk)

                chunk = f.read(chunk_size)

        if calculate_sha256:
            return md5_hash.hexdigest(), sha256_hash.hexdigest()

        return md5_hash.hexdigest()

    except FileNotFoundError:
        print(f""File not found: {filepath}"")
        return None, None if calculate_sha256 else None

    except PermissionError:
        print(f""Permission denied for file: {filepath}"")
        return None, None if calculate_sha256 else None

    except IOError as e:
        print(f""I/O error occurred while processing the file: {e}"")
        return None, None if calculate_sha256 else None
```
