import hashlib

def calculate_hashes(file_path, chunk_size=8192, calculate_sha256=False):
    md5 = hashlib.md5()
    sha256 = hashlib.sha256()

    try:
        with open(file_path, 'rb') as file:
            while True:
                chunk = file.read(chunk_size)
                if not chunk:
                    break
                md5.update(chunk)
                sha256.update(chunk)
    except FileNotFoundError:
        print(""File not found."")
        return None
    except PermissionError:
        print(""Permission denied."")
        return None
    except IOError:
        print(""IO error occurred."")
        return None

