import time
from Crypto.Random import get_random_bytes

class Event_InformationTag:
    def __init__(self):
        self._tags = {}

    def generate_tag(self, event_name):
        timestamp = str(time.time()).replace('.', '')
        randomness = get_random_bytes(5).hex()  # for a stronger randomness you may use UUID

        tag = f""{event_name}_{timestamp}_{randomness}""
        self._tags[tag] = event_name

        return tag
```

