```python
import random
from math import ceil

class CustomRandomGenerator:
    def __init__(self, min_val, max_val):
        self._random = random
        self._range_min = min_val
        self._range_max = max_val

    def GenerateFloat(self, step=0.1):
        return round(self._random.uniform(self._range_min, self._range_max), 2)

    def GenerateInt(self, step=1):
        return ceil(round(self._random.uniform(self._range_min, self._range_max)) / step) * step
