```python
import math

def check_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    sqrt_n = int(math.floor(math.sqrt(n)))
    for i in range(3, sqrt_n + 1, 2):
        if n % i == 0:
            return False
    return True

def get_user_input():
    while True:
        user_input = input(""Enter a number to check if it's prime (or 'q' to quit): "")

        # Check for exit condition
        if user_input.lower() == 'q':
            break

        # Validate the input and process it if valid
        try:
            num = int(user_input)
            print('Number {} is prime.'.format(num) if check_prime(num) else 'Number {} is not prime.'.format(num)) 
        except ValueError:
            print(""That's not a valid number."")
```

