import json
from collections import OrderedDict

def merge_dicts_and_convert(*args):
    merged = {}
    for i, lst in enumerate(args[:2]):
        for dct in lst:
            if isinstance(dct, dict):
                merged.update(dct)
    converted = {json.dumps(k, sort_keys=True): v for k, v in merged.items()}
    new_list = args[2] + list(converted.keys())

    nested_dict = {}
    current = nested_dict
    for i, key in enumerate(new_list):
        if i == len(args[0]) or i == len(args[1]):  # start of second list
            current['_dicts'] = OrderedDict()  # add additional level for dict keys
            current = current['_dicts']
        current[key] = i
    return nested_dict
```

