import json

def complex_merge_dicts(dict_list1, dict_list2, str_list):
    merged_dict = {}
    for dict1 in dict_list1:
        merged_dict.update(dict1)
    for dict2 in dict_list2:
        merged_dict.update(dict2)

    json_str_list = []
    for item in merged_dict.values():
        if isinstance(item, dict):
            json_str_list.append(json.dumps(item))
        else:
            json_str_list.append(str(item))

    final_keys = [f""{key}"" for key in str_list]

    nested_dict = {}
    for index, value in enumerate(final_keys):
        nested_key = value.split('.') if '.' in value else value
        current_level = nested_dict
        for part in nested_key[:-1]:
            if part not in current_level:
                current_level[part] = {}
            current_level = current_level[part]

        current_level[nested_key[-1]] = index

    return nested_dict
``` 

