print(test)  # Expected output: ['apple', 'grapes', 'banana', 'cherry', 'apple', 'mango']

# Test with no occurrence of string ""pear""
try:
    insert_string(test, ""peach"", find=""pear"")
except ValueError as e:
    print(""ValueError raised as expected:"", str(e))  # Expected output: String to find was not found in the list.

# Test with no string to find specified
try:
    insert_string(test, ""grapes"")
except TypeError as e:
    print(""TypeError raised as expected:"", str(e))  # Expected output: Missing 1 required positional argument: 'string_to_insert'

# Test with negative index
try:
    insert_string(test, ""grapes"", find=""apple"", after_index=-2)
except ValueError as e:
    print(""ValueError raised as expected:"", str(e))  # Expected output: String to find was not found in the list.
