In conclusion, this integration fosters innovation by leveraging complementary strengths from different programming languages—Python",590,,"['Your task involves creating two classes - `ImageProcessor` in Python and `FileProcessor` in Java. Here is a sample implementation for these classes:

**1. ImageProcessor class in Python:**
```python
import cv2
import numpy as np

class ImageProcessor:
    def __init__(self, image_path):
        self.image = cv2.imread(image_path)
        if self.image is None:
            raise Exception('File not found or invalid image format')

    def resize_image(self, width, height):
        return cv2.resize(self.image, (width, height))

    def apply_grayscale(self):
        return cv2.cvtColor(self.image, cv2.COLOR_BGR2GRAY)

    def apply_blur(self, kernel=(5, 5)):
        return cv2.blur(self.image, kernel)

    def rotate_image(self, angle):
        rows, cols = self.image.shape[:2]
        M = cv2.getRotationMatrix2D((cols / 2, rows / 2), angle, 1)
        return cv2.warpAffine(self.image, M, (cols, rows))

    def flip_image(self, direction):
        return cv2.flip(self.image, direction)

    def detect_faces(self, cascade='haarcascade_frontalface_default.xml', scaleFactor=1.1, minNeighbors=5, minSize=(30, 30)):
        face_cascade = cv2.CascadeClassifier(cascade)
        gray = cv2.cvtColor(self.image, cv2.COLOR_BGR2GRAY)
        faces = face_cascade.detectMultiScale(gray, scaleFactor, minNeighbors, minSize)
        return len(faces)
