class SecureDataProcessor:
    def __init__(self):
        self.cache = {}

    def _processItem(self, item, filter_attributes=None, transforms=None):
        if isinstance(item, dict):
            result = {}
            for key in item:
                if filter_attributes and key not in filter_attributes:
                    continue
                transformed_key = transforms[key](key) if transforms and key in transforms else key
                processed_value = self._processItem(item[key], None, transforms) if isinstance(item[key], dict) else item[key]
                result[transformed_key] = processed_value
            return result
        elif isinstance(item, list):
