def calculate_md5(filepath, chunk_size=8192):
    md5 = hashlib.md5()
    with open(filepath, 'rb') as f:
        for block in iter(lambda: f.read(chunk_size), b''):
            md5.update(block)
    return md5.hexdigest()

def verify_integrity(filepath, ref_hash):
