import hashlib
import concurrent.futures
import os

def calculate_md5(file_path, chunk_size=65536):
    hash_md5 = hashlib.md5()
    with open(file_path, ""rb"") as f:
        for chunk in iter(lambda: f.read(chunk_size), b""""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def batch_calculate_md5(file_paths, num_threads=4):
    with concurrent.futures.ThreadPoolExecutor(max_workers=num_threads) as executor:
        results = {executor.submit(calculate_md5, file_path): file_path for file_path in file_paths}
        for future in concurrent.futures.as_completed(results):
            file_path = results[future]
            try:
                md5_hash = future.result()
            except Exception as exc:
                print(f""{file_path} generated an exception: {exc}"")
            else:
                print(f""{file_path} md5 is {md5_hash}"")
    return results.values(), future.result()

def verify_integrity(file_path, reference_hash):
    calculated_hash = calculate_md5(file_path)
    return calculated_hash == reference_hash

def check_file_integrity(file_paths, reference_hashes):
    result_dict = {}
    with concurrent.futures.ThreadPoolExecutor() as executor:
