Python TaskScheduler class:
```python
import threading
import time
from paho.mqtt import client as mqtt_client

class TaskScheduler():
    def __init__(self, broker='localhost', port=1883):
        self.broker = broker
        self.port = port
        self.client = None
        self._create_mqtt_connection()

    def _create_mqtt_connection(self):
        def on_connect(client, userdata, flags, rc):
            if rc == 0:
                print(""Connected to MQTT Broker."")
            else:
                print(""Failed to connect. Return Code: %d"", rc)
        self.client = mqtt_client.Client()
        self.client.on_connect = on_connect
        self.client.connect(self.broker, self.port)
        self.client.loop_start()

    def invoke_task(self, task, delay):
        threading.Timer(delay, lambda: self._invoke(task)).start()

    def _invoke(self, task):
        print(""Invoking task..."")
        try:
            task()
        except Exception as e:
            print(""Error occurred while invoking the task."", str(e))
            self.client.publish('task_termination', ""Task failed with error: "" + str(e))
```

