import csv
import os
from collections import defaultdict

def read_and_validate_csv(file_path, permission_level, column_name):
    if not os.path.exists(file_path):
        raise FileNotFoundError(""File not found."")

    if permission_level not in [1, 2]:
        raise ValueError(""Invalid permission level."")

    sensitive_columns = [""credit_score"", ""salary"", ""SSN""]

    if permission_level == 1 and column_name in sensitive_columns:
        raise ValueError(""Access denied for sensitive data."")

    try:
        total_value = 0
        row_count = 0
        with open(file_path, 'r') as csv_file:
            csv_reader = csv.DictReader(csv_file)
            for row in csv_reader:
                if all(value.strip() for value in row.values()):
                    total_value += float(row[column_name])
                    row_count += 1
                else:
                    print(f""Invalid data detected: {row}"")

            average_value = total_value / row_count if row_count > 0 else None

        return average_value

    except Exception as e:
        raise ValueError(f""An error occurred during file processing: {e}"")

try:
    average_salary = read_and_validate_csv('data.csv', 2, 'salary')
    print(f""Average Salary: {average_salary}"")
except Exception as e:
    print(e)
