```python
import asyncio
from threading import Semaphore, Thread
import time

class QueryExecutor():
    def __init__(self, worker_pool=5, rate_limit=10):
        self.semaphore = Semaphore(rate_limit)
        self.worker_pool = worker_pool
        self._task_queue = asyncio.Queue()

    async def _worker(self, i, queue):
        while True:
            print(f'Worker {i} started')
            try:
                query = await queue.get()
            except Exception as e:
                print('QueryExecutor worker failed', str(e))
            else:
                self._execute_query(query)
            finally:
                queue.task_done()

    def _execute_query(self, query):
        retry = 0
        while True:
            try:
                # Simulate database operation
                print('Executing query')
                time.sleep(1)  # simulate db operation
                break
            except Exception as e:
                if retry < 5:
                    print('Query failed, retrying', str(e))
                    retry += 1
                    time.sleep(retry * 2)  # wait for increasing intervals
                else:
                    raise e

    def start(self):
        loop = asyncio.get_event_loop()

        tasks = []
        for i in range(self.worker_pool):
            task = loop.create_task(self._worker(i, self._task_queue))
            tasks.append(task)

    def add_query(self, query):
        self._task_queue.put_nowait(query)

    def shutdown(self):
        print('Shutting down QueryExecutor')
        for i in range(self._task_queue.qsize()):
            self.add_query(None)  # Add sentinel values to stop workers

        self._task_queue.join()  # Wait until all tasks are completed
