```python
import json

class JSONFactory:
    _registry = {}

    @classmethod
    def register(cls, id):
        def decorator(func):
            cls._registry[id] = func
            return func
        return decorator

    @classmethod
    def get(cls, id):
        return cls._registry.get(id)

    @classmethod
    def create_instance(cls, data, id):
        if isinstance(data, str):
            data = json.loads(data)

            if 'type' in data:
                factory_func = cls._registry.get(id)
                return factory_func(data) if factory_func else None
            else:
                raise ValueError(""Missing type key"")
        else:
            raise TypeError(""Data must be a JSON string or dictionary"")

class Person:
    def __init__(self, name):
        self.name = name

    @classmethod
    def create_from_json(cls, json_data):
        return cls(json_data['name'])

    def __str__(self):
        return f'Person(name={self.name})'

class Company:
    def __init__(self, name, employees_count):
        self.name = name
        self.employees_count = employees_count

    @classmethod
    def create_from_json(cls, json_data):
        return cls(json_data['name'], json_data['employees_count'])

# Registering new factory functions with IDs for person and company creation
JSONFactory.register('person')(Person.create_from_json)
JSONFactory.register('company')(Company.create_from_json)

# Creating instances using the registered factory functions
json_str = '{""type"": ""person"", ""name"": ""John Doe""}'
instance = JSONFactory.create_instance(json_str, 'person')
print(instance)  # Output: Person(name='John Doe')

json_str_company = '{""type"": ""company"", ""name"": ""TechCorp"", ""employees_count"": 100}'
instance_company = JSONFactory.create_instance(json_str_company, 'company')
