def sortAndExtractSequenceNumber(file_path):

    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()
            lines.sort()
            last_line = lines[-1]
            sequence_number_index = last_line.find('Sequence Number')

            if sequence_number_index != -1:
                start_index = sequence_number_index + len('Sequence Number:') 
                end_index = last_line.find(' ', start_index)
                sequence_number_str = last_line[start_index:end_index]
                return int(sequence_number_str)
            else:
                raise ValueError('No Sequence Number found in the file.')
    except FileNotFoundError:
        print(f""Error: The file '{file_path}' was not found."")
