    def encrypt_message(msg):
        cipher = DES3.new(DES3_KEY, DES3.MODE_CFB, IV=IV)
        msg += ' ' * (8 - len(msg) % 8) # padding for Triple DES
        return base64.b64encode(cipher.encrypt(msg))

    @staticmethod  
    def decrypt_message(msg):
        cipher = DES3.new(DES3_KEY, DES3.MODE_CFB, IV=IV)
        return cipher.decrypt(base64.b64decode(msg))

    @staticmethod  
    def generate_custom_data():
        id_ = DataDecryptedCustomListGenerator.generate_unique_id(DataDecryptedCustomListGenerator.active_ids)
        is_active = random.choice([True, False])
        name = DataDecryptedCustomListGenerator.generate_random_string()

        DataDecryptedCustomListGenerator.active_ids.add(id_)

        return CustomData(id_, is_active, name)

    @staticmethod  
    def generate_custom_data_list_and_decode_message(count: int, data_structure: List[CustomData], encrypted_message: str):
        try:
            for _ in range(count):
                data = DataDecryptedCustomListGenerator.generate_custom_data()
                data_structure.append(data)

            if len(encrypted_message) % 8 != 0: # check if message is padded to be decoded by Triple DES
                raise ValueError(""Encrypted message must be a multiple of 8 bytes"")

            deciphered = DataDecryptedCustomListGenerator.decrypt_message(encrypted_message)

            msg_hash = hashlib.sha256(encrypted_message.encode()).hexdigest()
            if msg_hash not in cache:
                cache[msg_hash] = deciphered

            return data_structure, cache[msg_hash]

        except Exception as e:
            logging.error(""Error occurred while processing the message: "" + str(e))
            logging.error(""Original encrypted message: "" + encrypted_message)
``` 

Note: This code requires pycryptodome library to be installed. To install, you can use pip:
```bash
pip install pycryptodome
