```python
class Node(object):
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

class BST(object):
    def __init__(self):
        self.root = None

    def insert_node(self, root, key):
        if not root:
            return Node(key)

        if key < root.key:
            root.left = self.insert_node(root.left, key)
        elif key > root.key:
            root.right = self.insert_node(root.right, key)

        return root

    def build_tree(self, max_depth, node_count, data_capacity):
        if not 0 <= max_depth <= 32 or node_count < 1:
            raise ValueError(""Invalid input values"")

        self.root = None
        import random
        for _ in range(node_count):
            key = random.randint(1, data_capacity)
            self.root = self.insert_node(self.root, key)
```
