```python
import hashlib
import csv
from typing import List, Dict, Any

class DataProcessor:
    def __init__(self, user_roles):
        self.user_roles = user_roles

    def calculate_hashes(self, file_path: str) -> Dict[str, str]:
        md5_hash = hashlib.md5()
        sha256_hash = hashlib.sha256()

        with open(file_path, ""rb"") as f:
            for byte_block in iter(lambda: f.read(4096),b""""):
                md5_hash.update(byte_block)
                sha256_hash.update(byte_block)

        return {'md5': md5_hash.hexdigest(), 'sha256': sha256_hash.hexdigest()}

    def process_file(self, file_path: str, valid_columns: List[str], expected_hashes: Dict[str, str]) -> List[Dict[str, Any]]:
        processed_data = []

        hashes = self.calculate_hashes(file_path)
        if hashes != expected_hashes:
            return None

        with open(file_path, 'r') as f:
            reader = csv.DictReader(f)

            for row in reader:
                is_valid = all([row[column] == self.user_roles[column](row[column]) for column in valid_columns if column in self.user_roles])

                if is_valid:
                    processed_data.append(row)

        return processed_data or None
``` 

